    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 7 لا يفوق 1686 هو <span dir=\"ltr\" class=\"expr\">7 × 240</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">7 × 240 = 1680</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">1686 - 1680 = 6</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">6 &lt; 7</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">1686 = 7 × 240 + 6</span>"},{"quoi":"الجواب","math":"صواب"}],
