    correction: [{"quoi":"نفكّك العبارة","math":"<span dir=\"ltr\" class=\"expr\">n<sup>2</sup> + n = n(n + 1)</span>"},{"quoi":"ما هو العدد الأوّلي","math":"العدد الأوّلي له قاسمان فقط: 1 و نفسه"},{"quoi":"العبارة جداء","math":"العبارة مكتوبة جداء عوامل، فهي ليست أوّلية بصفة عامّة"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">n = 3</span> نجد <span dir=\"ltr\" class=\"expr\">3<sup>2</sup> + 3 = 12</span>"},{"quoi":"نفكّك المثال","math":"<span dir=\"ltr\" class=\"expr\">12 = 3(3 + 1)</span>"},{"quoi":"الجواب","math":"خطأ"}],
