    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">81<sup>148</sup> = 3<sup>592</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>592</sup> + n × 3<sup>591</sup> = 3<sup>591</sup>(3 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">63 = 9 × 7</span>"},{"quoi":"العامل 9 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>591</sup> = 3<sup>2</sup> × 3<sup>589</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3 + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3 = 3</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">3 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 4 ؛ 11 ؛ 18 ؛ 25 ؛ 32 ؛ 39 ؛ 46 ؛ 53</span>"}],
