    enonce: "ليكن n عددا صحيحا طبيعيا أصغر من 60 و لتكن <span dir=\"ltr\" class=\"expr\">E = 81<sup>207</sup> + n × 3<sup>826</sup></span> أوجد كلّ القيم الممكنة لـ n لتقبل E القسمة على 21",
    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">81<sup>207</sup> = 3<sup>828</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>828</sup> + n × 3<sup>826</sup> = 3<sup>826</sup>(3<sup>2</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">21 = 3 × 7</span>"},{"quoi":"العامل 3 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">3<sup>826</sup> = 3 × 3<sup>825</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 3 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">3<sup>2</sup> + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">3<sup>2</sup> = 9</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">9 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 5 ؛ 12 ؛ 19 ؛ 26 ؛ 33 ؛ 40 ؛ 47 ؛ 54</span>"}],
